  String _scheduledRowLine() {
    final now = nowFn().millisecondsSinceEpoch;
    final eta = scheduledNextDueMs < 0
        ? ''
        : scheduledNextDueMs <= now
        ? ' · due now'
        : ' · next in '
              '${ScheduledMessageQueue.formatDelay(Duration(milliseconds: scheduledNextDueMs - now))}';
